using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class AddLink673Tests {
  static int checks;static string output;
  static void Check(bool value,string label){checks++;File.AppendAllText(Path.Combine(output,"progress.txt"),label+Environment.NewLine);if(!value)throw new Exception(label);}
  static void Call(RobotDesignerForm robot,string name){typeof(RobotDesignerForm).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(robot,null);}
  static void Select(RobotDesignerForm robot,RobotJoint joint){typeof(RobotDesignerForm).GetField("selectedJoint",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(robot,joint.Id);}
  static void Joined(RobotDocument doc,RobotJoint parent,RobotJoint child){var fk=RobotKinematics.Evaluate(doc,0,false);Check((fk[child.Id].Origin-fk[parent.Id].Tip).Length<1e-7,"child origin equals parent tip: "+child.Name);var a=fk[parent.Id].Tip-fk[parent.Id].Origin;var b=fk[child.Id].Tip-fk[child.Id].Origin;a.Normalize();b.Normalize();Check((a-b).Length<1e-7,"child continues parent world direction: "+child.Name);Check(Math.Abs(child.Length-140)<1e-7,"new length 140 mm");}
  public static int View(string folder){try{var doc=RobotDocument.Parse(File.ReadAllText(Path.Combine(folder,"EightAxis.robot.json")));var build=RobotCad.Build(doc);using(var scene=new WpfScene()){foreach(var entry in build.Entries.Values.Where(e=>e.Guide||!doc.Joints.Skip(5).Any(j=>j.Id==e.JointId)))scene.Hidden.Add(entry.Id);scene.SetResult(new Result{P=new Parameters{Kind=9},Model=build.Model,Robot=build},false);scene.Camera.Yaw=225;scene.Camera.Pitch=20;scene.SavePng(Path.Combine(folder,"J6-J8.png"),1400,1000);scene.Camera.Yaw=135;scene.Camera.Pitch=25;scene.SavePng(Path.Combine(folder,"J6-J8-reverse.png"),1400,1000);}return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"view-error.txt"),ex.ToString());return 1;}}
  static void Generate(CADKernel kernel,RobotDocument doc,RobotJoint joint){File.AppendAllText(Path.Combine(output,"progress.txt"),"Generating "+joint.Name+Environment.NewLine);File.WriteAllText(Path.Combine(output,"spec-"+joint.Id+".json"),CADDocument.Serializer().Serialize(ProceduralBodySpec.Build(doc,joint,joint.BodyGenerator)),Encoding.UTF8);joint.GeneratedBody=ProceduralBodySpec.Generate(kernel,doc,joint,joint.BodyGenerator);File.WriteAllText(Path.Combine(output,"body-"+joint.Id+".json"),CADDocument.Serializer().Serialize(joint.GeneratedBody.Result),Encoding.UTF8);Check(joint.GeneratedBody.Result.GeometryValid,"native housing valid: "+joint.Name+" / "+string.Join("; ",joint.GeneratedBody.Result.Issues.Where(i=>i.Status=="error").Select(i=>i.Message)));Check(joint.GeneratedBody.Result.Parts.All(p=>p.Volume>0&&p.Step!=null&&p.Preview!=null),"positive native solids and real meshes");Check(!joint.GeneratedBody.Result.ReadyForManufacture,"no manufacturing approval");}
  public static int Run(string folder){output=Path.GetFullPath(folder);Directory.CreateDirectory(output);checks=0;var sink=UiMessage.TestSink;var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};UiMessage.TestSink=text=>{throw new Exception("Unexpected UI error: "+text);};string empty=Path.Combine(output,"empty.robot.json");new RobotDocument().Save(empty);
   using(var robot=new RobotDesignerForm(empty)){
    robot.SetDocument(RobotDocument.EnclosedExample());Select(robot,robot.Document.Joints.Last());
    for(int i=0;i<2;i++){var parent=robot.Document.Joints.Last();Call(robot,"AddJoint");Check(robot.Document.Joints.Count==7+i,"AddJoint actually added link");Joined(robot.Document,parent,robot.Document.Joints.Last());}
    var doc=robot.Document.Clone();using(var kernel=new CADKernel()){foreach(var joint in doc.Joints.Skip(5).Reverse())Generate(kernel,doc,joint);var build=RobotCad.Build(doc);Check(build.Model.Valid,"extended six-axis assembly builds");Check(RobotConnections.Validate(build).Count==0,"native flange frames and bolt holes coincide");}
    doc.Save(Path.Combine(output,"EightAxis.robot.json"));
    robot.SetDocument(doc);Select(robot,robot.Document.Joints.Last());var source=robot.Document.Joints.Last();var oldCount=robot.Document.Joints.Count;var before=RobotKinematics.Evaluate(robot.Document,0,false);Call(robot,"AddParallelBranch");var parallel=robot.Document.Joints.Last();var after=RobotKinematics.Evaluate(robot.Document,0,false);Check(robot.Document.Joints.Count==oldCount+1&&parallel.ParentId==null,"parallel branch is an independent chain");Check((after[parallel.Id].Origin-before[source.Id].Origin).Length>=100,"parallel branch is visibly separated");var da=before[source.Id].Tip-before[source.Id].Origin;var db=after[parallel.Id].Tip-after[parallel.Id].Origin;da.Normalize();db.Normalize();Check((da-db).Length<1e-7,"parallel branch preserves current world direction");Check(parallel.BodyGenerator!=null&&!ReferenceEquals(parallel.BodyGenerator,source.BodyGenerator)&&parallel.MotorFrame==source.MotorFrame,"branch copies mechanical and body settings independently");using(var kernel=new CADKernel())Generate(kernel,robot.Document,parallel);Call(robot,"Undo");Check(robot.Document.Joints.Count==oldCount,"undo removes parallel branch");Call(robot,"Redo");Check(robot.Document.Joints.Count==oldCount+1,"redo restores parallel branch");robot.Document.Save(Path.Combine(output,"ParallelBranch.robot.json"));
    foreach(var direction in new[]{new Vector3D(0,1,0),new Vector3D(0,0,-1),new Vector3D(-2,3,4)}){var d=RobotDocument.EnclosedExample();var p=d.Joints.Last();p.EndX=direction.X*70;p.EndY=direction.Y*70;p.EndZ=direction.Z*70;robot.SetDocument(d);Select(robot,p);Call(robot,"AddJoint");Joined(robot.Document,p,robot.Document.Joints.Last());Check(Math.Abs(Vector3D.DotProduct(robot.Document.Joints.Last().Axis,direction/direction.Length))<.71,"selected joint axis avoids longitudinal direction");}
    robot.SetDocument(RobotDocument.Example());Select(robot,robot.Document.Joints.Last());Call(robot,"AddJoint");var legacy=robot.Document.Joints.Last();Check(Math.Abs(new Vector3D(legacy.OffsetX,legacy.OffsetY,legacy.OffsetZ).Length-100)<1e-7,"legacy beam example retains 100 mm side step");
    robot.SetDocument(new RobotDocument());Call(robot,"AddJoint");Check(robot.Document.Joints.Count==1&&robot.Document.Joints[0].OffsetZ==95,"first joint keeps 95 mm base offset");
   }
   File.WriteAllText(Path.Combine(output,"add-link673-results.txt"),"PASS "+checks+" checks",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(output,"add-link673-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{UiMessage.TestSink=sink;AppSettings.Current=old;}}
 }
}
